#include <edward/ai/memory_store.hpp>
#include <QCoreApplication>
#include <QTemporaryDir>
#include <cassert>
int main(int argc, char** argv) { QCoreApplication app(argc, argv); QTemporaryDir dir; edward::ai::MemoryStore store(dir.filePath("memory.sqlite")); edward::ai::MemoryEntry text{edward::ai::MemoryScope::Global, {}, "component.text.color", "value", "blue"}; assert(store.remember(text, false).ok); assert(store.query({edward::ai::MemoryScope::Global, {}, "component.text.color", "value"}).isEmpty()); assert(store.remember(text, true).ok); assert(store.flush(edward::ai::FlushReason::Idle).ok); const auto textResult = store.query({edward::ai::MemoryScope::Global, {}, "component.text.color", "value"}); assert(!textResult.isEmpty() && textResult.front().value == "blue"); auto border = text; border.nameSpace = "component.border.color"; border.value = "red"; assert(store.remember(border, true).ok); assert(store.flush(edward::ai::FlushReason::Export).ok); const auto textAfterBorder = store.query({edward::ai::MemoryScope::Global, {}, "component.text.color", "value"}); assert(!textAfterBorder.isEmpty() && textAfterBorder.front().value == "blue"); assert(store.forget(text).ok); assert(store.flush(edward::ai::FlushReason::ProjectOpen).ok); assert(store.query({edward::ai::MemoryScope::Global, {}, "component.text.color", "value"}).isEmpty()); }
